from datetime import UTC, date, datetime, timedelta

import pytest

from snowfall.vendor.junction_one.client import JunctionOneClient
from snowfall.vendor.junction_one.models import autogenerated as auto_models
from snowfall.vendor.junction_one.models import base as models


@pytest.mark.integration()
async def test_e2e_flow(remote_junction_one_client: JunctionOneClient) -> None:  # noqa: WPS217,WPS218
    # Create a trip.
    trip = await remote_junction_one_client.create_trip(
        models.TripCreateRequest(
            name="end2end trip test",
            start_date=date(2024, 10, 10),
            end_date=date(2024, 10, 12),
            org_id=635604,
            booker_ids=[2602533],
        ),
    )
    assert trip.id
    assert trip.booker_ids

    # Check that the trip exists (note that there could be unrelated trips in there).
    trips = await remote_junction_one_client.list_trips(models.TripListRequest())
    assert trip.id in {trip.id for trip in trips}

    # Get a hotel reference.
    hotels = await remote_junction_one_client.search_hotels(
        auto_models.SearchHotelsRequest(
            checkin_date=datetime.now(tz=UTC).date() + timedelta(days=1),
            checkout_date=datetime.now(tz=UTC).date() + timedelta(days=3),
            latitude=48.856614,
            longitude=2.3522219,
            org_id=635604,
            user_ids=[2602533],
        ),
    )
    assert hotels.hotels
    hotel = hotels.hotels[0]
    assert hotel.refs

    # Get a room from the hotel.
    rooms = await remote_junction_one_client.get_hotel_details(
        models.HotelDetailsRequest(refs=hotel.refs),
    )
    assert rooms.rooms
    room = rooms.rooms[0]

    # Create the tripboard.
    tripboard_create_response = await remote_junction_one_client.create_tripboard(
        models.TripboardCreateRequest(
            booker_id=trip.booker_ids[0],
            trip_id=trip.id,
        ),
    )
    assert tripboard_create_response.boards
    tripboard = tripboard_create_response.boards[0]
    assert tripboard.id

    # Add the hotel room to the tripboard.
    await remote_junction_one_client.add_refs(
        models.AddRefsRequest(
            id=tripboard.id,
            trip_id=trip.id,
            hotel_refs=room.ref,
        ),
    )

    # Check that the room was added.
    tripboards = (await remote_junction_one_client.get_tripboard(trip.id)).boards
    assert tripboards
    assert len(tripboards) == 1
    assert tripboards[0].refs
    assert len(tripboards[0].refs) == 1
    ref = tripboards[0].refs[0]
    assert ref.ref == room.ref

    # Delete the trip.
    await remote_junction_one_client.delete_trip(
        models.TripDeleteRequest(id=trip.id),
    )

    # Check that the trip no longer exists.
    trips = await remote_junction_one_client.list_trips(models.TripListRequest())
    assert trip.id not in {trip.id for trip in trips}
